    backgroundJobs = pgTable("background_jobs", {
      id: uuid("id").primaryKey().defaultRandom(),
      queueName: varchar("queue_name", { length: 100 }).notNull(),
      // 'analysis', 'reports', 'alerts'
      jobType: varchar("job_type", { length: 100 }).notNull(),
      // Specific job type within queue
      data: jsonb("data").notNull(),
      // Job payload
      priority: integer("priority").default(0),
      // Higher numbers = higher priority
      status: jobStatusEnum("status").default("pending"),
      maxRetries: integer("max_retries").default(3),
      attempts: integer("attempts").default(0),
      error: text("error"),
      // Last error message
      result: jsonb("result"),
      // Job result data
      runAt: timestamp("run_at").defaultNow(),
      // When job should run
      startedAt: timestamp("started_at"),
      // When processing started
      completedAt: timestamp("completed_at"),
      // When job completed
      failedAt: timestamp("failed_at"),
      // When job failed permanently
      createdAt: timestamp("created_at").defaultNow(),
      updatedAt: timestamp("updated_at").defaultNow()
    }, (table) => [
      index("idx_background_jobs_queue_status").on(table.queueName, table.status),
      index("idx_background_jobs_run_at").on(table.runAt),
      index("idx_background_jobs_priority").on(table.priority)
    ]);
