      async getDecisionOutcomesByOrganization(organizationId, period) {
        const conditions = [eq(decisionOutcomes.organizationId, organizationId)];
        if (period) {
          const now = /* @__PURE__ */ new Date();
          let startDate;
          switch (period) {
            case "month":
              startDate = new Date(now.getFullYear(), now.getMonth(), 1);
              break;
            case "quarter":
              const quarter = Math.floor(now.getMonth() / 3);
              startDate = new Date(now.getFullYear(), quarter * 3, 1);
              break;
            case "year":
              startDate = new Date(now.getFullYear(), 0, 1);
              break;
            default:
              startDate = new Date(now.getFullYear(), 0, 1);
          }
          conditions.push(sql`${decisionOutcomes.createdAt} >= ${startDate}`);
        }
        return await db.select().from(decisionOutcomes).where(and(...conditions)).orderBy(desc(decisionOutcomes.createdAt));
      }
      async getROIMetrics(organizationId, period) {
        const outcomes = await this.getDecisionOutcomesByOrganization(organizationId, period);
        if (outcomes.length === 0) {
          return {
            totalCostSaved: 0,
            totalTimeRecovered: 0,
            totalDecisions: 0,
            avgExecutionTime: 0,
            avgConfidenceScore: 0,
            successRate: 0
          };
        }
        const totalCostSaved = outcomes.reduce((sum2, o) => {
          const cost = o.costOfImplementation ? parseFloat(o.costOfImplementation.toString()) : 0;
          return sum2 + cost;
        }, 0);
        const totalTimeRecovered = outcomes.reduce((sum2, o) => sum2 + (o.timeToImplement || 0), 0);
        const totalDecisions = outcomes.length;
        const avgExecutionTime = totalTimeRecovered / totalDecisions;
        const confidenceMap = { low: 25, medium: 50, high: 75, very_high: 100 };
        const avgConfidenceScore = outcomes.reduce((sum2, o) => {
          const score = o.confidence ? confidenceMap[o.confidence] : 0;
          return sum2 + score;
        }, 0) / totalDecisions;
        const successCount = outcomes.filter(
          (o) => o.actualOutcome === "successful" || o.effectiveness === "high" || o.effectiveness === "excellent"
        ).length;
        const successRate = successCount / totalDecisions * 100;
        return {
          totalCostSaved,
          totalTimeRecovered,
          totalDecisions,
          avgExecutionTime,
          avgConfidenceScore,
          successRate
        };
      }
